    "Form1.form.yaml": "formatVersion: 1\nproperties:\n  Caption: 퀴즈\n  Width: 400\n  Height: 300\ncontrols:\n  - name: lblNumber\n    type: Label\n    properties:\n      Left: 16\n      Top: 12\n      Width: 368\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 40\n      Width: 368\n  - name: lstChoices\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 72\n      Width: 232\n      Height: 116\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 264\n      Top: 72\n      Width: 120\n      Height: 116\n  - name: chkShowAnswer\n    type: CheckBox\n    properties:\n      Caption: 틀리면 정답 보여 주기\n      Left: 16\n      Top: 200\n      Width: 240\n  - name: btnCheck\n    type: Button\n    properties:\n      Caption: 정답 확인\n      Left: 16\n      Top: 248\n      Width: 136\n  - name: lblScore\n    type: Label\n    properties:\n      Left: 168\n      Top: 252\n      Width: 216\n",
    "Form1.gbas": "' 작은 퀴즈: 문제를 보여 주고, ListBox의 보기 가운데 하나를 고르면\n' 맞았는지 알려 주며 점수를 셉니다. 최고 점수는 저장해 두었다가 다음에\n' 실행할 때도 보여 줍니다. 그림 문제는 프로젝트의 그림(pictures 폴더)을\n' Image에 보여 줍니다.\nDim questions(6) As String\nDim choices(6) As String    ' 보기들을 | 로 이어 붙인 글자\nDim answers(6) As Integer   ' 정답 보기의 번호(0부터)\nDim pictures(6) As String   ' 문제의 그림 이름. 그림이 없는 문제는 \"\"\nDim current As Integer\nDim score As Integer\nDim best As Integer\n\nSub Form_Load()\n    questions(0) = \"대한민국의 수도는 어디일까요?\"\n    choices(0) = \"부산|서울|대구|인천\"\n    answers(0) = 1\n    questions(1) = \"윤년이 아닌 해는 며칠일까요?\"\n    choices(1) = \"360일|365일|366일|370일\"\n    answers(1) = 1\n    questions(2) = \"1기압에서 물이 끓는 온도는?\"\n    choices(2) = \"50도|80도|100도|120도\"\n    answers(2) = 2\n    questions(3) = \"세종대왕이 만든 글자는?\"\n    choices(3) = \"한자|한글|가나|알파벳\"\n    answers(3) = 1\n    questions(4) = \"7 × 8은 얼마일까요?\"\n    choices(4) = \"54|56|58|64\"\n    answers(4) = 1\n    questions(5) = \"이 도형의 이름은?\"\n    choices(5) = \"사각형|원|삼각형|오각형\"\n    answers(5) = 2\n    pictures(5) = \"triangle.png\"\n    questions(6) = \"이 도형의 꼭짓점은 몇 개일까요?\"\n    choices(6) = \"4개|5개|6개|8개\"\n    answers(6) = 1\n    pictures(6) = \"pentagon.png\"\n    ' 지난 실행까지의 최고 점수. 저장된 것이 없으면 \"0\"입니다.\n    best = CInt(GetSetting(\"best\", \"0\"))\n    ShowQuestion(0)\nEnd Sub\n\nSub ShowQuestion(number As Integer)\n    current = number\n    lblNumber.Caption = \"문제 \" & (number + 1) & \" / \" & (UBound(questions) + 1)\n    lblQuestion.Caption = questions(number)\n    ' 그림 이름을 넣으면 그 그림을, \"\"을 넣으면 아무것도 보여 주지 않습니다.\n    imgQuestion.Picture = pictures(number)\n    ' Clear()는 고른 항목도 지웁니다. 그래서 고른 것이 있었다면\n    ' lstChoices_Changed가 실행되고, ListIndex는 -1(고른 것 없음)이 됩니다.\n    lstChoices.Clear()\n    For Each choice In Split(choices(number), \"|\")\n        lstChoices.AddItem(choice)\n    Next\n    lblScore.Caption = \"점수: \" & score & \" · 최고 점수: \" & best\nEnd Sub\n\nSub lstChoices_Changed()\n    ' ListIndex가 바뀔 때마다 실행됩니다: 보기를 고를 때, 그리고 Clear()로\n    ' 고른 것이 없어질 때(ListIndex = -1).\n    If lstChoices.ListIndex = -1 Then\n        btnCheck.Caption = \"정답 확인\"\n    Else\n        btnCheck.Caption = \"확인: \" & lstChoices.Text\n    End If\nEnd Sub\n\nSub btnCheck_Click()\n    If lstChoices.ListIndex = -1 Then\n        MsgBox(\"먼저 보기를 하나 고르세요.\")\n        Exit Sub\n    End If\n    If lstChoices.ListIndex = answers(current) Then\n        score = score + 1\n        MsgBox(\"정답입니다!\")\n    ElseIf chkShowAnswer.Checked Then\n        MsgBox(\"틀렸습니다. 정답: \" & lstChoices.List(answers(current)))\n    Else\n        MsgBox(\"틀렸습니다.\")\n    End If\n    If current < UBound(questions) Then\n        ShowQuestion(current + 1)\n    Else\n        Dim message As String = (UBound(questions) + 1) & \"문제 가운데 \" & score & \"문제를 맞혔습니다.\"\n        If score > best Then\n            ' SaveSetting으로 저장한 값은 프로그램을 다시 실행해도 남습니다.\n            best = score\n            SaveSetting(\"best\", best)\n            message = message & \" 새 최고 점수입니다!\"\n        End If\n        MsgBox(message & \" 처음부터 다시 합니다.\")\n        score = 0\n        ShowQuestion(0)\n    End If\nEnd Sub\n",
